-- 5. CURRICULUM PROGRAMS & BLOCKS
SELECT ((m.id - 1) * 4) + c.id,
       m.id,
       c.id,
       CONCAT(m.code, '-', c.code),
       CONCAT('Chương trình đào tạo ', m.name, ' - ', c.name),
       140
FROM majors m
CROSS JOIN cohorts c;

SELECT p.id, b.code, b.name, b.block_type, b.required_subject_count, b.required_credits, b.elective_subject_count, b.elective_credits, b.display_order
FROM curriculum_programs p
CROSS JOIN (
    SELECT 'GDDC' AS code, 'Giáo dục đại cương' AS name, 'COMPULSORY' AS block_type, 6 AS required_subject_count, 17 AS required_credits, 0 AS elective_subject_count, 0 AS elective_credits, 1 AS display_order
    UNION ALL SELECT 'CSNG', 'Cơ sở ngành', 'COMPULSORY', 4, 12, 0, 0, 2
    UNION ALL SELECT 'CN', 'Chuyên ngành', 'COMPULSORY', 4, 12, 0, 0, 3
    UNION ALL SELECT 'TC03', 'Tự chọn chuyên ngành 1', 'ELECTIVE', 0, 0, 1, 3, 4
    UNION ALL SELECT 'TC05', 'Tự chọn chuyên ngành 2', 'ELECTIVE', 0, 0, 1, 3, 5
    UNION ALL SELECT 'TC06', 'Tự chọn chuyên ngành 3', 'ELECTIVE', 0, 0, 1, 3, 6
) b;

-- Block subjects
SELECT cb.id, s.id, 1
FROM curriculum_blocks cb
CROSS JOIN subjects s
WHERE cb.code = 'GDDC' AND s.subject_code IN ('BS101', 'BS102', 'BS104', 'BS105', 'EN101');

SELECT cb.id, s.id, 1
FROM curriculum_blocks cb
JOIN curriculum_programs cp ON cb.program_id = cp.id
CROSS JOIN subjects s
WHERE cb.code = 'GDDC' AND cp.major_id IN (1, 3, 4) AND s.subject_code = 'BS103';

SELECT cb.id, s.id, 1 FROM curriculum_blocks cb JOIN curriculum_programs cp ON cb.program_id = cp.id CROSS JOIN subjects s
WHERE cb.code = 'CSNG' AND cp.major_id = 1 AND s.subject_code IN ('IT101', 'IT201', 'IT202', 'IT203');

SELECT cb.id, s.id, 1 FROM curriculum_blocks cb JOIN curriculum_programs cp ON cb.program_id = cp.id CROSS JOIN subjects s
WHERE cb.code = 'CN' AND cp.major_id = 1 AND s.subject_code IN ('IT301', 'IT302', 'IT303', 'IT304');

SELECT cb.id, s.id, 0 FROM curriculum_blocks cb JOIN curriculum_programs cp ON cb.program_id = cp.id CROSS JOIN subjects s
WHERE cb.code = 'TC03' AND cp.major_id = 1 AND s.subject_code IN ('EN201', 'JA101');

SELECT cb.id, s.id, 0 FROM curriculum_blocks cb JOIN curriculum_programs cp ON cb.program_id = cp.id CROSS JOIN subjects s
WHERE cb.code = 'TC05' AND cp.major_id = 1 AND s.subject_code = 'IT305';

SELECT cb.id, s.id, 0 FROM curriculum_blocks cb JOIN curriculum_programs cp ON cb.program_id = cp.id CROSS JOIN subjects s
WHERE cb.code = 'TC06' AND cp.major_id = 1 AND s.subject_code = 'IT401';

SELECT cb.id, s.id, 1 FROM curriculum_blocks cb JOIN curriculum_programs cp ON cb.program_id = cp.id CROSS JOIN subjects s
WHERE cb.code = 'CSNG' AND cp.major_id = 2 AND s.subject_code IN ('BA101', 'BA102', 'BA103', 'BA201');

SELECT cb.id, s.id, 1 FROM curriculum_blocks cb JOIN curriculum_programs cp ON cb.program_id = cp.id CROSS JOIN subjects s
WHERE cb.code = 'CN' AND cp.major_id = 2 AND s.subject_code IN ('BA202', 'BA301', 'BA302');

SELECT cb.id, s.id, 1 FROM curriculum_blocks cb JOIN curriculum_programs cp ON cb.program_id = cp.id CROSS JOIN subjects s
WHERE cb.code = 'CSNG' AND cp.major_id = 3 AND s.subject_code IN ('EE101', 'EE201', 'EE202');

SELECT cb.id, s.id, 1 FROM curriculum_blocks cb JOIN curriculum_programs cp ON cb.program_id = cp.id CROSS JOIN subjects s
WHERE cb.code = 'CN' AND cp.major_id = 3 AND s.subject_code IN ('EE301', 'EE302');

SELECT cb.id, s.id, 1 FROM curriculum_blocks cb JOIN curriculum_programs cp ON cb.program_id = cp.id CROSS JOIN subjects s
WHERE cb.code = 'CSNG' AND cp.major_id = 4 AND s.subject_code IN ('ME101', 'ME201', 'ME202');

SELECT cb.id, s.id, 1 FROM curriculum_blocks cb JOIN curriculum_programs cp ON cb.program_id = cp.id CROSS JOIN subjects s
WHERE cb.code = 'CN' AND cp.major_id = 4 AND s.subject_code IN ('ME301', 'ME302');

